1	import { Router } from "express";
2	import { z } from "zod";
3	import type { Db } from "@paperclipai/db";
4	import { forbidden, unauthorized } from "../errors.js";
5	import { inboxDismissalService, logActivity } from "../services/index.js";
6	import { expressHandler } from "../http/express-adapter.js";
7	import type { Handler, RequestCtx } from "../http/types.js";
8	import type { StorageService } from "../storage/types.js";
9	
10	const inboxDismissalSchema = z.object({
11	  itemKey: z.string().trim().min(1).regex(/^(approval|join|run):.+$/, "Unsupported inbox item key"),
12	});
13	
14	/** Minimal company access check using fields available on ActorContext. */
15	function assertCompanyAccessCtx(ctx: RequestCtx, companyId: string) {
16	  if (!ctx.actor) throw unauthorized();
17	  if (ctx.actor.type === "agent" && ctx.actor.companyId !== companyId) {
18	    throw forbidden("Agent key cannot access another company");
19	  }
20	  // Board actor company-list enforcement is handled by the Express auth
21	  // middleware before the Handler is reached.
22	  // TODO(cloudflare): re-enforce companyIds list in Workers auth layer.
23	}
24	
25	function buildHandlers(db: Db) {
26	  const svc = inboxDismissalService(db);
27	
28	  // server/src/routes/inbox-dismissals.ts:16
29	  const getInboxDismissals: Handler = async (ctx) => {
30	    const companyId = ctx.param("companyId") ?? "";
31	    assertCompanyAccessCtx(ctx, companyId);
32	    if (ctx.actor?.type !== "board") {
33	      return Response.json({ error: "Board authentication required" }, { status: 403 });
34	    }
35	    if (!ctx.actor.userId) {
36	      return Response.json({ error: "Board user context required" }, { status: 403 });
37	    }
38	    const dismissals = await svc.list(companyId, ctx.actor.userId);
39	    return Response.json(dismissals);
40	  };
41	
42	  // server/src/routes/inbox-dismissals.ts:31
43	  const postInboxDismissal: Handler = async (ctx) => {
44	    const companyId = ctx.param("companyId") ?? "";
45	    assertCompanyAccessCtx(ctx, companyId);
46	    if (ctx.actor?.type !== "board") {
47	      return Response.json({ error: "Board authentication required" }, { status: 403 });
48	    }
49	    if (!ctx.actor.userId) {
50	      return Response.json({ error: "Board user context required" }, { status: 403 });
51	    }
52	
53	    const body = await ctx.json();
54	    const parsed = inboxDismissalSchema.parse(body);
55	
56	    const dismissal = await svc.dismiss(companyId, ctx.actor.userId, parsed.itemKey, new Date());
57	
58	    // ctx.actor lacks `runId`; log with null runId.
59	    // TODO(cloudflare): thread runId through ActorContext.
60	    await logActivity(db, {
61	      companyId,
62	      actorType: "user",
63	      actorId: ctx.actor.userId,
64	      agentId: null,
65	      runId: null,
66	      action: "inbox.dismissed",
67	      entityType: "company",
68	      entityId: companyId,
69	      details: {
70	        userId: ctx.actor.userId,
71	        itemKey: dismissal.itemKey,
72	        dismissedAt: dismissal.dismissedAt,
73	      },
74	    });
75	
76	    return Response.json(dismissal, { status: 201 });
77	  };
78	
79	  return { getInboxDismissals, postInboxDismissal };
80	}
81	
82	export function inboxDismissalRoutes(db: Db) {
83	  const router = Router();
84	  const { getInboxDismissals, postInboxDismissal } = buildHandlers(db);
85	
86	  const storageSentinel = new Proxy({} as StorageService, {
87	    get(_target, prop) {
88	      throw new Error(`inboxDismissal handler unexpectedly accessed storage.${String(prop)}`);
89	    },
90	  });
91	  const deps = { db, storage: storageSentinel };
92	
93	  router.get("/companies/:companyId/inbox-dismissals", expressHandler(getInboxDismissals, deps));
94	  router.post("/companies/:companyId/inbox-dismissals", expressHandler(postInboxDismissal, deps));
95	
96	  return router;
97	}
